import java.util.*;
/* Analysis: generic Leaderboard accepts Comparator<? super T>; wildcard List<? extends T> supports bulk add. Lexicographic comparison is transitive: points desc, goal difference desc, name asc. One sort O(n log n), copied list O(n) space. Comparable suits one natural order; Comparator allows reuse. */
public class Q5 {
 static class Team{final String name;final int points,diff;Team(String n,int p,int d){name=n;points=p;diff=d;}public String toString(){return name+"("+points+","+diff+")";}}
 static class Leaderboard<T>{List<T>items=new ArrayList<>();Comparator<? super T>order;Leaderboard(Comparator<? super T>c){order=c;}void add(T x){items.add(x);}void addAll(List<? extends T>x){items.addAll(x);}List<T>ranking(){List<T>c=new ArrayList<>(items);c.sort(order);return c;}}
 public static void main(String[]x){Comparator<Team>c=Comparator.comparingInt((Team t)->t.points).reversed().thenComparing(Comparator.comparingInt((Team t)->t.diff).reversed()).thenComparing(t->t.name,String.CASE_INSENSITIVE_ORDER);Leaderboard<Team>b=new Leaderboard<>(c);b.add(new Team("Panthers",9,4));b.add(new Team("Eagles",9,6));b.add(new Team("Cobras",6,1));b.add(new Team("Bisons",9,4));System.out.println(b.ranking());}
}